<template><div class="grid gap-4 md:grid-cols-2"><el-card><template #header>Departments</template><div v-for="d in deptStats" :key="d.department_id" class="flex justify-between py-2 border-b last:border-0"><span class="font-medium">{{ d.department_name }}<span class="text-gray-400 text-sm ml-2">{{ d.headcount }}p</span></span><span class="text-sm text-gray-500">Skills {{ d.skill_coverage }} Avg{{ d.avg_skill_level }}</span></div></el-card><el-card><template #header>Key People</template><div v-for="c in critical" :key="c.employee_id" class="flex justify-between py-2 border-b last:border-0"><span>{{ c.full_name }}<span class="text-gray-400 text-sm ml-2">{{ c.department_name }}</span></span><el-tag size="small">{{ c.team_size }} depends</el-tag></div><div v-if="!critical.length" class="text-gray-400 text-center py-4">No data</div></el-card><el-card class="md:col-span-2"><template #header>Org Tree</template><div v-for="n in orgTree" :key="n.employee_id" class="py-1" :style="{marginLeft:n.depth*24+'px'}"><div class="flex items-center gap-2"><div class="h-2 w-2 rounded-full" :class="n.depth===0?'bg-orange-400':'bg-gray-300'"></div><span>{{ n.full_name }}</span><span class="text-xs text-gray-400">{{ n.department_name }}</span></div></div><div v-if="!orgTree.length" class="text-gray-400 text-center py-4">No data</div></el-card></div></template><script setup lang="ts">import {ref,onMounted}from 'vue';import {getOrgDepartments,getOrgCritical,getOrgTree}from '@/api/hrms';const emit=defineEmits(['update-title']);emit('update-title','Org Panorama');const deptStats=ref<any[]>([]);const critical=ref<any[]>([]);const orgTree=ref<any[]>([]);onMounted(async()=>{try{const[a,b,c]=await Promise.all([getOrgDepartments(),getOrgCritical(),getOrgTree()]);deptStats.value=(a as any).data||[];critical.value=(b as any).data||[];orgTree.value=(c as any).data||[]}catch(e){}})</script>
